package br.com.ismtelecom.pos;

import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.util.Base64;

/** Marca oficial ISM Telecom, extraída da segunda página de ISM Telecom_logo.pdf.
 * PNG de dimensões fixas: escala proporcional, sem redesenho, estiramento ou rotação. */
final class IsmOfficialLogo {
    private IsmOfficialLogo() {}
    private static final String PNG = "";
    static Bitmap decode() {
        byte[] bytes = Base64.decode(PNG, Base64.DEFAULT);
        Bitmap bitmap = BitmapFactory.decodeByteArray(bytes, 0, bytes.length);
        if (bitmap == null) throw new IllegalStateException("Logomarca ISM inválida");
        return bitmap;
    }
}
